"""Normalize release records at the input boundary.

Import direction: this module imports nothing from the other three modules; it
is the identity/replay layer that planner.py consumes. The specific failure
code travels in the exception message because planner.py maps ``str(exc)``
straight into the transport result.
"""


class JournalError(ValueError):
    pass


def _id_list(value, key):
    """Read an optional array of change IDs; reject anything malformed."""
    if value is None:
        value = []
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    ids = []
    for entry in value:
        if not isinstance(entry, str) or not entry:
            raise JournalError("invalid-change")
        ids.append(entry)
    return ids


def _dedupe(ids):
    seen = set()
    unique = []
    for entry in ids:
        if entry not in seen:
            seen.add(entry)
            unique.append(entry)
    return unique


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    by_id = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = _dedupe(_id_list(row.get("depends_on"), "depends_on"))
        change = {"id": row["id"], "component": row["component"], "units": row["units"]}
        previous = by_id.get(change["id"])
        if previous is not None:
            if (previous["component"] != change["component"]
                    or previous["units"] != change["units"]
                    or set(previous["depends_on"]) != set(depends_on)):
                raise JournalError("conflicting-change")
            continue
        change["depends_on"] = depends_on
        by_id[change["id"]] = change
        changes.append(change)
    return changes


def read_journal(applied):
    if applied is None:
        return []
    if not isinstance(applied, list):
        raise JournalError("invalid-change")
    return _dedupe(_id_list(applied, "applied"))


def read_retain(retain, applied):
    """Read the G2 rollback retain list: applied IDs that must remain.

    Defaults to empty (absent or null). A non-list value or a malformed entry is
    ``invalid-retain``, and so is an ID the persisted journal does not report as
    applied: naming it would ask to keep something that is not there.
    """
    if retain is None:
        return []
    if not isinstance(retain, list):
        raise JournalError("invalid-retain")
    ids = []
    for entry in retain:
        if not isinstance(entry, str) or not entry:
            raise JournalError("invalid-retain")
        ids.append(entry)
    ids = _dedupe(ids)
    applied_set = set(applied)
    for entry in ids:
        if entry not in applied_set:
            raise JournalError("invalid-retain")
    return ids


def check_graph(changes, applied):
    """Fail on dangling dependencies, unknown applied IDs, or cycles."""
    known = {change["id"] for change in changes}
    for change in changes:
        for dependency in change["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
    for entry in applied:
        if entry not in known:
            raise JournalError("unknown-dependency")
    if order(changes) is None:
        raise JournalError("dependency-cycle")


def order(changes):
    """Topological order with lexicographic tie-breaking, or None on a cycle."""
    pending = {change["id"]: len(change["depends_on"]) for change in changes}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        for dependency in change["depends_on"]:
            dependents[dependency].append(change["id"])
    eligible = sorted(change_id for change_id, count in pending.items() if count == 0)
    ranked = []
    while eligible:
        current = eligible.pop(0)
        ranked.append(current)
        for dependent in dependents[current]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                eligible.append(dependent)
        eligible.sort()
    if len(ranked) != len(pending):
        return None
    return ranked

planner.py.text:
"""Compose policy, journal data and the dependency graph into a plan.

Import direction: planner.py -> journal.py, policy.py (unchanged). Only
release.py imports planner.py. No file, network or deployment side effects:
the plan is advisory only and never executes a release.
"""
from journal import (JournalError, check_graph, order, read_changes,
                     read_journal, read_retain)
from policy import PolicyError, read_policy


def failure(code):
    """The one place an error envelope is built.

    Every failure path returns this complete object (empty actions, zero
    units); callers must never observe a partially built plan, which is the
    "disallowed operation emits no partial actions" rule from SPEC/G2.
    """
    return {"status": "error", "error": code, "actions": [], "units": 0}


def required_dependencies(changes, roots):
    """Return the roots plus every transitive dependency of them.

    Used by G2 retention: a retained change cannot stay without everything it
    (transitively) depends on. check_graph has already rejected cycles, and the
    visited set keeps the walk linear even when many nodes are retained.
    """
    by_id = {change["id"]: change["depends_on"] for change in changes}
    needed = set()
    stack = list(roots)
    while stack:
        current = stack.pop()
        if current in needed:
            continue
        needed.add(current)
        stack.extend(by_id[current])
    return needed


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = read_policy(request)
        changes = read_changes(request.get("changes"))
        applied = read_journal(request.get("applied"))
        # Retain is a rollback-only field; a plan request ignores it.
        retain = read_retain(request.get("retain"), applied) if action == "rollback" else []
        check_graph(changes, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    ranked = order(changes)
    units_by_id = {change["id"]: change["units"] for change in changes}
    applied_set = set(applied)
    if action == "rollback":
        # G2: retained changes and their applied transitive dependencies stay;
        # every other applied change is emitted in the original deterministic
        # reverse order. Budget was validated but never caps rollback.
        retained = required_dependencies(changes, retain) & applied_set
        actions = [change_id for change_id in reversed(ranked)
                   if change_id in applied_set and change_id not in retained]
        return {"status": "ok", "actions": actions,
                "units": sum(units_by_id[change_id] for change_id in actions)}
    # Plan: replay first (applied entries satisfy dependencies and spend no new
    # budget), then the G2 staging quota on the emitted units. The quota is
    # checked before emitting anything, so a rejected plan has no partial actions.
    actions = [change_id for change_id in ranked if change_id not in applied_set]
    units = sum(units_by_id[change_id] for change_id in actions)
    if units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

