"""Validate, coalesce and index release records at the input boundary.

This module owns identity and replay *shape*: it never sorts, budgets or decides
which actions run. The planner consumes its output and owns graph/order.

Replay accounting note: ``applied`` is the caller's persisted release journal,
not state held by this service. Every request replays it from scratch, so this
module must be able to answer "which changes are already done" without touching
any external store.
"""


class JournalError(ValueError):
    pass


def _is_int(value):
    # bool is a subclass of int in Python; SPEC says integers exclude booleans,
    # so a strict type check is required rather than isinstance().
    return type(value) is int


def _read_depends(row):
    depends = row.get("depends_on")
    if depends is None:
        return ()
    if not isinstance(depends, list):
        raise JournalError("invalid-change")
    # Dependencies are an unordered set: order is irrelevant and repeated
    # entries carry no extra meaning. A self-reference is rejected here even
    # though it would also be caught as a cycle later: it is a record-shape
    # bug, and SPEC gives ``invalid-change`` precedence over graph errors.
    seen = set()
    for dep in depends:
        if not isinstance(dep, str) or not dep or dep == row["id"]:
            raise JournalError("invalid-change")
        seen.add(dep)
    return tuple(sorted(seen))


def read_changes(records):
    """Return normalized records: dicts with id/component/units/depends_on(tuple)."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or not _is_int(row.get("units")) or row["units"] < 1):
            raise JournalError("invalid-change")
        changes.append({
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_depends(row),
        })
    return changes


def read_applied(records):
    """Return the persisted journal as an ordered, de-duplicated tuple of IDs."""
    if records is None:
        return ()
    # A bare string is iterable, so ``"ab"`` would silently become ``["a","b"]``
    # and an out-of-type journal could approve changes that were never applied.
    # Type-check the container before iterating it.
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    ids = []
    seen = set()
    for entry in records:
        if not isinstance(entry, str) or not entry:
            raise JournalError("invalid-change")
        if entry not in seen:
            seen.add(entry)
            ids.append(entry)
    return tuple(ids)


def coalesce(changes):
    """Collapse identical duplicate records; reject same-ID conflicting records.

    Identity is the *whole record* (id, component, units and dependency set),
    not just the id. Two records sharing an id but differing anywhere else mean
    the upstream data is inconsistent; silently keeping the last one would
    change what gets deployed, so we fail with ``conflicting-change`` instead.
    """
    by_id = {}
    for change in changes:
        previous = by_id.get(change["id"])
        if previous is None:
            by_id[change["id"]] = change
        elif previous != change:
            raise JournalError("conflicting-change")
    return by_id

