"""Compose policy, journal data and the dependency graph into a plan.

Dependency direction: this module may import policy and journal; neither may
import this module. Transport (release.py) only imports ``plan``.
"""
import heapq

from journal import JournalError, coalesce, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    """The one place an error envelope is built.

    Every failure path returns this complete object (empty actions, zero
    units); callers must never observe a partially built plan, which is the
    "disallowed operation emits no partial actions" rule from SPEC.
    """
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _check_graph(by_id, applied):
    """Reject unknown dependency targets and unknown applied IDs.

    Checked before cycle detection on purpose: a graph that is both dangling and
    cyclic reports ``unknown-dependency`` (the first SPEC-ordered fault), and
    rollback needs every applied ID to exist in the graph before it can be
    replayed. Cycles are detected separately in ``_topological``.
    """
    for change in by_id.values():
        for dep in change["depends_on"]:
            if dep not in by_id:
                raise JournalError("unknown-dependency")
    for entry in applied:
        if entry not in by_id:
            raise JournalError("unknown-dependency")


def _topological(by_id):
    """Return the full deterministic topological order of every change.

    Tie-breaking is lexicographic smallest ID among *currently eligible*
    changes (deps satisfied), implemented with a min-heap. Sorting ``depends_on``
    in journal and using a heap here makes the order independent of input order
    and of dict/hash iteration, so it is reproducible across processes.

    Ordering is computed over the *full* graph, applied nodes included. That is
    what lets ``plan`` filter applied entries (their dependents still see their
    dependencies satisfied) and ``rollback`` walk the reverse of one identical
    order rather than a second, possibly different, ordering.
    """
    indegree = {cid: len(change["depends_on"]) for cid, change in by_id.items()}
    dependents = {cid: [] for cid in by_id}
    for cid, change in by_id.items():
        for dep in change["depends_on"]:
            dependents[dep].append(cid)

    ready = [cid for cid, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        cid = heapq.heappop(ready)
        order.append(cid)
        for dependent in dependents[cid]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    # Fewer emitted nodes than changes means at least one cycle. We raise
    # instead of returning the partial order: a partial order is exactly the
    # "partial actions" that must never reach the caller.
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied_ids = read_applied(request.get("applied"))
        by_id = coalesce(changes)
        _check_graph(by_id, applied_ids)
        order = _topological(by_id)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    applied = set(applied_ids)
    if request["action"] == "rollback":
        # Rollback replays the applied journal in reverse dependency order.
        # Budget was validated above but intentionally does NOT cap rollback:
        # stopping an unroll midway is worse than overrunning a plan budget.
        emitted = [cid for cid in reversed(order) if cid in applied]
    else:
        # Already applied changes satisfy dependencies (order was computed on
        # the full graph) but must not be re-emitted, so they consume no new
        # budget. Accounting therefore happens on exactly the emitted set.
        emitted = [cid for cid in order if cid not in applied]

    units = sum(by_id[cid]["units"] for cid in emitted)
    # Budget is checked after replay/dedup so duplicates are charged once.
    if request["action"] == "plan" and units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": emitted, "units": units}

