"""Compose policy and journal data into a plan.

Import direction: planner.py -> journal.py, policy.py (unchanged). Nothing
imports planner.py except the release.py entrypoint.

Responsibilities: build the dependency graph, detect bad targets/cycles,
produce the deterministic topological order, apply replay and budget rules, and
assemble the exact four-field result. No file, network or deployment side
effects: the plan is advisory only and never executes a release.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, read_policy

def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(actions, units):
    return {"status": "ok", "actions": actions, "units": units}


def build_graph(changes, applied_ids):
    """Return (units_by_id, deps_by_id) after validating ids against the journal.

    Every dependency and every persisted applied id must name a change in
    ``changes``; otherwise the request is internally inconsistent and fails with
    ``unknown-dependency``. This is the only place that decides id existence, so
    journal.py can stay purely structural.
    """
    units_by_id = {}
    deps_by_id = {}
    for change in changes:
        units_by_id[change["id"]] = change["units"]
    for change in changes:
        for dep in change["depends_on"]:
            if dep not in units_by_id:
                raise JournalError("unknown-dependency")
        deps_by_id[change["id"]] = tuple(change["depends_on"])
    for applied_id in applied_ids:
        if applied_id not in units_by_id:
            raise JournalError("unknown-dependency")
    return units_by_id, deps_by_id


def topological_order(units_by_id, deps_by_id):
    """Return the full deterministic topological order of all changes.

    Kahn's algorithm with a min-heap keyed by change id: among changes whose
dependencies are already emitted, the lexicographically smallest id goes
    next. That tie-break is what makes plans reproducible across runs.

    The order is computed over *all* changes, including already applied ones, so
    that rollback can invert the same canonical sequence (SPEC G1) and plan
    replay does not change relative order. If any node remains unresolved the
    graph has a cycle somewhere, including a self-loop, and we fail with
    ``dependency-cycle`` instead of emitting a partial order.
    """
    remaining = {}
    dependents = {change_id: [] for change_id in units_by_id}
    for change_id, deps in deps_by_id.items():
        remaining[change_id] = len(deps)
        for dep in deps:
            dependents[dep].append(change_id)
