"""Compose policy and journal data into a plan.

Import direction: planner.py imports journal.py and policy.py and is imported by
release.py. Both of its dependencies are leaves, so no cycle can form. This
module owns graph construction, deterministic ordering and result assembly; it
never touches stdin/stdout.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, allows, limit_for


def failure(code):
    """The single error shape. Every failure carries no partial actions.

    A disallowed operation must not leak a partial plan, so actions/units are
    fixed here rather than at each raise site.
    """
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _ordered(changes, applied):
    """Return the full deterministic topological order of every change.

    The order covers all changes, including already-applied ones, because
    rollback needs to walk applied changes in reverse of their original
    execution order. Replay state only affects which subset is emitted later.

    Kahn's algorithm with a heap over currently eligible IDs gives lexicographic
    tie-breaking among eligible nodes. It is iterative, so the cycle case that
    a recursive DFS would blow the stack on (a long cycle) terminates by simply
    leaving nodes unemitted.
    """
    by_id = {change["id"]: change for change in changes}
    for change in changes:
        for dependency in change["depends_on"]:
            if dependency not in by_id:
                raise JournalError("unknown-dependency")
    unknown = applied - by_id.keys()
    if unknown:
        # The persisted journal referencing an ID absent from `changes` means the
        # caller's two inputs disagree; guessing would emit an unrunnable plan.
        raise JournalError("unknown-dependency")

    waiting = {change_id: len(change["depends_on"])
               for change_id, change in by_id.items()}
    dependents = {change_id: [] for change_id in by_id}
    for change in changes:
        for dependency in change["depends_on"]:
            dependents[dependency].append(change["id"])

    eligible = [change_id for change_id, count in waiting.items() if count == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        current = heapq.heappop(eligible)
        order.append(current)
        for dependent in dependents[current]:
            waiting[dependent] -= 1
            if waiting[dependent] == 0:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        # A cycle blocked the drain. This check runs on the full graph, so a cycle
        # masked by `applied` (every member already released) still fails rather
        # than reporting success on an unsatisfiable graph.
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    """Validate the request, then assemble the success or failure object."""
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request)
        order = _ordered(changes, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    action = request["action"]
    if action == "rollback":
        # Only applied changes exist to undo, in reverse execution order. Budget
        # was validated above but intentionally does not cap the result.
        emitted = [change_id for change_id in reversed(order) if change_id in applied]
    else:
        # Already applied changes satisfy dependencies and spend no new budget,
        # so they are filtered before the ceiling is checked.
        emitted = [change_id for change_id in order if change_id not in applied]

    units = sum(change["units"] for change in changes if change["id"] in set(emitted))
    if allows(action) and units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": emitted, "units": units}

